// wf.listings.embed > "Batches"
// Listings without an embedding, in batches of 16 texts per Ollama request, sent one batch
// at a time (D-049: the HTTP node sends all its items at once).
const row = $input.first().json;
if (!row.job_id) throw new Error('job not found or already finished');
const cfg = row.cfg || {};
const todo = row.listings || [];
const model = cfg['ollama.embed_model'] || 'bge-m3';
const url = `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`;
const out = [];
for (let i = 0; i < todo.length; i += 16) {
  const b = todo.slice(i, i + 16);
  out.push({ json: { model, url, ids: b.map((x) => x.id), body: { model, input: b.map((x) => x.text), truncate: true } } });
}
if (!out.length) out.push({ json: { none: true, model, ids: [] } });
return out;

// wf.listings.embed > "Vectors": Ollama answer -> rows for app.store_listing_embeddings.
const batch = $('Loop batches').first().json;
let b = $input.first().json;
b = b.body !== undefined ? b.body : b;
if (typeof b === 'string') b = JSON.parse(b);
const v = b.embeddings || [];
if (v.length !== batch.ids.length) throw new Error(`embedding answer has ${v.length} vectors for ${batch.ids.length} texts`);
for (const x of v) if (!Array.isArray(x) || x.length !== 1024) throw new Error('embedding is not 1024 numbers');
return [{ json: { params: [batch.model, JSON.stringify(batch.ids.map((id, i) => ({ id, v: `[${v[i].join(',')}]` })))] } }];

// wf.listings.embed > "Summarize"
const start = $('Start job').first().json;
const n = (start.listings || []).length;
return [{ json: { job_id: start.job_id, status: 'succeeded', error: null, output: { listings_embedded: n } } }];

// Worker workflows (wf.kb.ingest, wf.eval.retrieval) > "Job failed"
// Error output of any step after "Start job": the job ends as failed with the
// (redacted) error text, so it never stays "running" after a handled failure.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const start = $('Start job').first().json;
const msg = redactPg(errorText($input.first().json)).slice(0, 500) || 'worker step failed without a message';
return [{ json: { job_id: start.job_id, status: 'failed', error: msg, output: { failed_step: true } } }];
